<?php

use Yoast\PHPUnitPolyfills\TestCases\TestCase;

require_once 'Zend/Db/Adapter/Sqlsrv.php';
require_once 'Zend/Db/Adapter/Pdo/Mssql.php';
require_once 'Zend/Db/Adapter/Pdo/Sqlsrv.php';

/**
 * SQL generated by limit() of the SQL Server adapters, no database connection needed
 *
 * @group      Zend_Db
 * @group      Zend_Db_Adapter
 */
class Zend_Db_Adapter_SqlServerLimitTest extends TestCase
{
    /**
     * @return array
     */
    public static function adapterProvider()
    {
        // limit() needs neither a connection nor the driver extension
        $adapters = [];
        foreach (['Sqlsrv', 'Pdo_Mssql', 'Pdo_Sqlsrv'] as $name) {
            $class = new ReflectionClass('Zend_Db_Adapter_' . $name);
            $adapters[$name] = [$class->newInstanceWithoutConstructor()];
        }

        return $adapters;
    }

    /**
     * @dataProvider adapterProvider
     */
    public function testOffsetOfAnOrderedQuery(Zend_Db_Adapter_Abstract $db)
    {
        $this->assertSame(
            'SELECT * FROM t ORDER BY a ASC, b DESC OFFSET 20 ROWS FETCH NEXT 10 ROWS ONLY',
            $db->limit('SELECT * FROM t ORDER BY a ASC, b DESC', 10, 20)
        );
        $this->assertSame(
            'SELECT * FROM t ORDER BY ABS(a) OFFSET 1 ROWS FETCH NEXT 5 ROWS ONLY',
            $db->limit('SELECT * FROM t ORDER BY ABS(a)', '5', '1')
        );
    }

    /**
     * @dataProvider adapterProvider
     */
    public function testOffsetOfAQueryWithoutOrder(Zend_Db_Adapter_Abstract $db)
    {
        $this->assertSame(
            'SELECT * FROM (SELECT DISTINCT a FROM t) AS inner_tbl ORDER BY (SELECT 0) OFFSET 3 ROWS FETCH NEXT 2 ROWS ONLY',
            $db->limit('SELECT DISTINCT a FROM t', 2, 3)
        );
    }

    /**
     * An ORDER BY of a subquery does not order the query
     *
     * @dataProvider adapterProvider
     */
    public function testOrderOfASubqueryIsNotTheOrderOfTheQuery(Zend_Db_Adapter_Abstract $db)
    {
        $sql = 'SELECT a FROM t WHERE b IN (SELECT TOP 5 b FROM u ORDER BY c)';

        $this->assertSame(
            'SELECT * FROM (' . $sql . ') AS inner_tbl ORDER BY (SELECT 0) OFFSET 3 ROWS FETCH NEXT 2 ROWS ONLY',
            $db->limit($sql, 2, 3)
        );
    }

    /**
     * Zend_Db_Select::limit(null, $offset) asks for PHP_INT_MAX rows
     *
     * @dataProvider adapterProvider
     */
    public function testOffsetWithoutCount(Zend_Db_Adapter_Abstract $db)
    {
        $this->assertSame(
            'SELECT * FROM t ORDER BY a OFFSET 5 ROWS',
            $db->limit('SELECT * FROM t ORDER BY a', PHP_INT_MAX, 5)
        );
    }

    /**
     * @dataProvider adapterProvider
     */
    public function testCountWithoutOffset(Zend_Db_Adapter_Abstract $db)
    {
        $this->assertSame('SELECT TOP 10 * FROM t ORDER BY a', $db->limit('SELECT * FROM t ORDER BY a', 10));
        $this->assertSame('SELECT DISTINCT TOP 10 a FROM t', $db->limit('SELECT DISTINCT a FROM t', 10));
    }

    /**
     * @dataProvider adapterProvider
     */
    public function testInvalidCount(Zend_Db_Adapter_Abstract $db)
    {
        $this->expectException(Zend_Db_Adapter_Exception::class);
        $db->limit('SELECT * FROM t', 0);
    }

    /**
     * @dataProvider adapterProvider
     */
    public function testInvalidOffset(Zend_Db_Adapter_Abstract $db)
    {
        $this->expectException(Zend_Db_Adapter_Exception::class);
        $db->limit('SELECT * FROM t', 1, -1);
    }
}
